package main

// Тесты обработки вывода команд: UTF-16, строки прогресса и обрезка длинного
// вывода. Все три вещи вылезли в одном месте — полевой прогон 8, сессия L2-sfc,
// где впервые реально отработали `sfc /scannow` (247 с) и
// `dism /online /cleanup-image /restorehealth` (191 с).
//
// Что было не так:
//   17. sfc — Unicode-приложение и пишет в pipe UTF-16LE. Агент декодировал его
//       как cp866, и в отчёт попала мешанина вида `\x1d\x040\x04G\x04...`
//       (модель честно сказала: итога проверки в выводе нет).
//   18. Итог долгой команды печатается ПОСЛЕДНИМ, а обрезка оставляла только
//       начало — вердикт sfc/DISM терялся и в отчёте, и в контексте модели.
//       Вдобавок сотни строк прогресса съедали весь бюджет обрезки.

import (
	"encoding/hex"
	"strings"
	"testing"
	"unicode/utf16"
	"unicode/utf8"
)

// realSfcUTF16Hex — НАСТОЯЩИЙ фрагмент вывода `sfc /scannow` из отчёта прогона 8
// (1994 байта UTF-16LE: начало сканирования и строки прогресса до ~40%).
const realSfcUTF16Hex = ""

func realSfcBytes(t *testing.T) []byte {
	t.Helper()
	b, err := hex.DecodeString(realSfcUTF16Hex)
	if err != nil {
		t.Fatalf("битый образец: %v", err)
	}
	return b
}

func TestDecodeUTF16RealSfcOutput(t *testing.T) {
	raw := realSfcBytes(t)
	got := decodeConsoleBytes(raw)
	if strings.ContainsRune(got, 0) {
		t.Fatalf("в выводе остались NUL-байты")
	}
	if strings.ContainsRune(got, '\x1d') || strings.Contains(got, "0\x04G") {
		t.Fatalf("вывод не раскодирован — те же «кракозябры», что в прогоне 8: %q", got[:80])
	}
	for _, want := range []string{
		"Начато сканирование системы.",
		"Этот процесс может занять некоторое время.",
		"Начало стадии проверки при сканировании системы.",
		"Проверка 10% завершена.",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("нет строки %q", want)
		}
	}
}

// ASCII-часть UTF-16 выглядит как валидный UTF-8, поэтому проверка UTF-16 обязана
// идти раньше проверки utf8.Valid — иначе NUL-байты дошли бы до отчёта.
func TestDecodeConsoleBytesPrefersUTF16OverUTF8(t *testing.T) {
	src := "whoami\r\nLENOVO\\Admin\r\n"
	raw := encodeUTF16LE(src)
	if !utf8.Valid(raw) {
		t.Skip("образец перестал быть валидным UTF-8 — тест потерял смысл")
	}
	if got := decodeConsoleBytes(raw); got != src {
		t.Fatalf("UTF-16 не распознан: получено %q, ожидали %q", got, src)
	}
}

func TestDecodeUTF16BigEndianWithBOM(t *testing.T) {
	src := "Защита ресурсов Windows не обнаружила нарушений целостности."
	raw := []byte{0xFE, 0xFF}
	for _, r := range utf16.Encode([]rune(src)) {
		raw = append(raw, byte(r>>8), byte(r))
	}
	if got := decodeConsoleBytes(raw); got != src {
		t.Fatalf("UTF-16BE с BOM не распознан: %q", got)
	}
}

// Бинарный дамп с нулями с ОБЕИХ сторон — не UTF-16, распознавать его нельзя.
func TestDecodeUTF16RejectsBinary(t *testing.T) {
	raw := []byte{0x00, 0x01, 0x00, 0x02, 0x00, 0x03, 0x00, 0x04, 0x00, 0x00, 0x00, 0x00}
	if s, ok := decodeUTF16(raw); ok {
		t.Fatalf("бинарные данные приняты за UTF-16: %q", s)
	}
}

// Обычный cp866-вывод не должен «уехать» в UTF-16-декодер.
func TestDecodeUTF16LeavesCP866Alone(t *testing.T) {
	cp866 := []byte{0x8a, 0xae, 0xe0, 0xaf, 0xae, 0xe0, 0xa0, 0xe2, 0xa8, 0xa2, 0xad, 0xa0, 0xef}
	if s, ok := decodeUTF16(cp866); ok {
		t.Fatalf("cp866 принят за UTF-16: %q", s)
	}
	if got := decodeConsoleBytes(cp866); got != "Корпоративная" {
		t.Fatalf("cp866-декодирование сломалось: %q", got)
	}
}

func TestCollapseProgressRealSfcLines(t *testing.T) {
	raw := realSfcBytes(t)
	got := finalizeOutput(raw)
	if strings.ContainsRune(got, '\r') {
		t.Fatalf("одиночные CR не нормализованы в LF")
	}
	if n := strings.Count(got, "завершена."); n > 3 {
		t.Fatalf("строки прогресса не свёрнуты: их %d", n)
	}
	if !strings.Contains(got, "[пропущено") {
		t.Fatalf("нет пометки о пропущенных строках прогресса:\n%s", got[:200])
	}
	// Образец обрезан на середине строки прогресса, поэтому проверяем
	// последнюю ПОЛНУЮ строку: свёртка обязана оставить именно её.
	if !strings.Contains(got, "Проверка 12% завершена.") {
		t.Fatalf("последняя полная строка прогресса потеряна:\n%s", got)
	}
}

func TestCollapseProgressDISMBars(t *testing.T) {
	var b strings.Builder
	for i := 0; i <= 100; i++ {
		b.WriteString("[====  12.7%  ]\n")
	}
	b.WriteString("Восстановление выполнено успешно.\n")
	got := collapseProgress(b.String())
	if strings.Count(got, "%") > 1 {
		t.Fatalf("полосы прогресса не свёрнуты:\n%s", got)
	}
	if !strings.Contains(got, "Восстановление выполнено успешно.") {
		t.Fatalf("итоговая строка потеряна:\n%s", got)
	}
}

// Проценты в осмысленных строках — не прогресс, их трогать нельзя.
func TestCollapseProgressKeepsMeaningfulLines(t *testing.T) {
	s := "Загрузка ЦП 45% (процесс chrome.exe)\nДиск C: заполнен на 93% \nПроверка 12% завершена.\nПроверка 13% завершена.\nПроверка 14% завершена.\n"
	got := collapseProgress(s)
	if !strings.Contains(got, "Загрузка ЦП 45% (процесс chrome.exe)") {
		t.Fatalf("осмысленная строка с процентом удалена:\n%s", got)
	}
	if !strings.Contains(got, "Диск C: заполнен на 93%") {
		t.Fatalf("осмысленная строка с процентом удалена:\n%s", got)
	}
	if strings.Count(got, "Проверка") != 1 {
		t.Fatalf("строки прогресса sfc не свёрнуты:\n%s", got)
	}
}

// --- обрезка -------------------------------------------------------------

// Итог долгой команды должен доживать до модели и отчёта.
func TestTruncateKeepsVerdictAtTail(t *testing.T) {
	s := "Начато сканирование системы.\n"
	for i := 0; i <= 100; i++ {
		s += "Проверка " + itoa(i) + "% завершена.\n"
	}
	s += "Защита ресурсов Windows не обнаружила нарушений целостности.\n"
	out := truncate(s, 400)
	if !strings.Contains(out, "Защита ресурсов Windows не обнаружила нарушений целостности.") {
		t.Fatalf("вердикт команды отрезан (дефект 18):\n%s", out)
	}
	if !strings.Contains(out, "пропущено") {
		t.Fatalf("нет пометки о пропущенной середине:\n%s", out)
	}
	if !strings.HasPrefix(out, "Начато сканирование системы.") {
		t.Fatalf("потеряно начало вывода:\n%s", out)
	}
}

// Сквозной путь как в бою: байты UTF-16 от sfc -> декод -> свёртка прогресса ->
// обрезка. Итог обязан быть в результате.
func TestLongCommandVerdictSurvivesFullPath(t *testing.T) {
	var b strings.Builder
	b.WriteString("Начато сканирование системы.\r\r\n")
	for i := 0; i <= 100; i++ {
		b.WriteString("Проверка " + itoa(i) + "% завершена.\r")
	}
	b.WriteString("\r\r\nПроверка 100% завершена.\r\r\nЗащита ресурсов Windows не обнаружила нарушений целостности.\r\r\n")
	out := truncate(finalizeOutput(encodeUTF16LE(b.String())), 4000)
	if !strings.Contains(out, "не обнаружила нарушений целостности") {
		t.Fatalf("итог sfc не дожил до модели:\n%s", out)
	}
	if strings.ContainsRune(out, 0) {
		t.Fatalf("в выводе NUL-байты")
	}
	if strings.Count(out, "завершена.") > 3 {
		t.Fatalf("строки прогресса съели бюджет обрезки")
	}
}

func TestTruncateKeepsRunesIntact(t *testing.T) {
	s := strings.Repeat("Д", 2001) // 4002 байта — граница обрезки внутри руны
	out := truncate(s, 4000)
	if strings.ContainsRune(out, utf8.RuneError) {
		t.Fatalf("в обрезанном выводе появился U+FFFD")
	}
	if !utf8.ValidString(out) {
		t.Fatalf("обрезанный вывод — не валидный UTF-8")
	}
	if !strings.HasPrefix(out, "Д") || !strings.HasSuffix(out, "Д") {
		t.Fatalf("сохранены не начало и конец: %q … %q", out[:4], out[len(out)-4:])
	}
	if !strings.Contains(out, "пропущено") {
		t.Fatalf("нет пометки об обрезке")
	}
}

func TestTruncateShortStringUnchanged(t *testing.T) {
	if got := truncate("короткая строка", 4000); got != "короткая строка" {
		t.Fatalf("короткая строка изменилась: %q", got)
	}
}

func TestTruncateASCII(t *testing.T) {
	if out := truncate(strings.Repeat("x", 10), 4); out != "xxxx" {
		t.Fatalf("для крошечного лимита ожидали ровно 4 байта, получили %q", out)
	}
}

// --- вспомогательное для тестов ------------------------------------------

func encodeUTF16LE(s string) []byte {
	u := utf16.Encode([]rune(s))
	out := make([]byte, 0, len(u)*2)
	for _, r := range u {
		out = append(out, byte(r), byte(r>>8))
	}
	return out
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	var d []byte
	for i > 0 {
		d = append([]byte{byte('0' + i%10)}, d...)
		i /= 10
	}
	return string(d)
}
